const TECH = [
  /* ---------- drawing foundations ---------- */
  { id: 'marks', s: 'found', n: 'Mark making', sum: 'Exploring every kind of mark one tool can make.', lvl: 1, mins: 15, ill: 'marks',
    what: 'Mark making is playing with the marks a single tool can make: dots, dashes, hatching, scribbles, zigzags, loops and lines that change with pressure. Every drawing is built from marks, so knowing your range gives you a vocabulary for texture, tone and energy.',
    why: 'Students who explore marks stop drawing everything with the same timid outline. It builds control, frees up nervous beginners, and gives them ways to show fur, bark, water or light later on.',
    steps: ['Fold a page into nine or twelve boxes.', 'Fill each box with one kind of mark: dots, dashes, curls, zigzags, crosses, scribbles, hatching, pressure lines.', 'Change one thing at a time: pressure, speed, spacing or the angle of the tool.', 'Try the same marks with a different tool, such as a pen, charcoal or a stick dipped in ink.', 'Label the boxes with words they suggest: rough, soft, fizzy, calm.', 'Use five of the marks in a small drawing, such as a tree or a pet.'],
    tips: ['Hold the pencil further back for looser, lighter marks, and closer to the tip for control.', 'Draw from the shoulder for long lines and from the wrist for small ones.', 'Keep the sampler: it becomes a reference sheet for textures later.'],
    mistakes: ['Pressing hard straight away, which dents the paper and leaves no room for darker marks.', 'Using one kind of mark for everything.', 'Rushing: slow, deliberate marks look more confident than fast scratchy ones.'],
    ex: 'Make a 12-box mark sampler with one tool, then repeat it with a different tool and compare.',
    kids: 'Call it a mark hunt and name the marks after weather or animals: rain dots, snake lines, thunder zigzags. Music works well too: fast songs, fast marks.',
    adults: 'Use it as a warm-up to loosen up. Ask for marks that feel calm, angry or joyful, which links technique to expression.',
    mat: ['HB, 2B and 6B pencils', 'Fineliner or ballpoint pen', 'Charcoal', 'Cartridge paper'], rel: ['line-weight', 'hatching', 'textures'] },
  { id: 'line-weight', s: 'found', n: 'Line weight', sum: 'Thick and thin lines that show light, depth and overlap.', lvl: 1, mins: 20, ill: 'lineweight',
    what: 'Line weight is how thick or dark a line is. Varying it makes a simple outline feel three-dimensional: heavier lines suggest shadow, weight and nearness, and lighter lines suggest light, distance and delicacy.',
    why: 'It’s the quickest way to make line drawings look polished, and it gets students thinking about light and depth before they ever shade.',
    steps: ['Draw the outline lightly first, with even, pale lines.', 'Decide where the light is coming from.', 'Go over the edges on the shadow side with a heavier line.', 'Thicken the lines where one object overlaps another, and where an object meets the ground.', 'Leave lines on the lit side thin, or even let them break.', 'Make the closest objects slightly bolder than those further away.'],
    tips: ['Use a softer pencil (4B) or a thicker pen for the heavy lines rather than pressing harder.', 'A line that swells and thins along its length looks lively. Practise turning the pen as you go.', 'Small gaps in lines on the light side let the drawing breathe.'],
    mistakes: ['Making every line heavy, which flattens the drawing.', 'Random thick lines that don’t follow any logic of light or overlap.', 'Tracing round the whole outline in one dark line at the end.'],
    ex: 'Draw three overlapping cups in pen, then add weight only where they overlap and on their shadow sides.',
    kids: 'Give them a thin and a thick marker: thin for the sunny side, thick for the shady side.',
    adults: 'Show examples from comics and architectural drawings, where line weight alone carries the form.',
    mat: ['2H and 4B pencils, or fineliners in 0.1, 0.5 and 0.8', 'Smooth cartridge paper'], rel: ['contour', 'pen-ink', 'light-form'] },
  { id: 'contour', s: 'found', n: 'Contour and blind contour', sum: 'Slow, continuous lines that follow every edge you see.', lvl: 1, mins: 20, ill: 'contour',
    what: 'Contour drawing follows the edges of a subject, outside and inside, with one slow, continuous line, as if the pencil were an ant crawling along the edge. Blind contour does this without looking at the paper at all.',
    why: 'It trains the eye and hand to work together and breaks the habit of drawing what we think something looks like instead of what is really there. The results are wobbly and full of character, which takes the pressure off.',
    steps: ['Put the subject (a hand, a shoe, a plant) close by and look at one point on its edge.', 'Place the pencil on the paper and imagine it touching that point.', 'Move your eyes very slowly along the edge, and let the pencil move at the same speed.', 'For blind contour, don’t look at the paper at all. For modified contour, glance down only when you change direction.', 'Follow inside edges too: folds, creases, the edge of a fingernail.', 'Keep going for three to five minutes without lifting the pencil.'],
    tips: ['Go slower than feels natural. The slowness is the point.', 'Push the pencil through a paper plate to hide the drawing hand and stop peeking.', 'Laugh at the results together. Nobody’s look “right”.'],
    mistakes: ['Peeking constantly, which turns it back into ordinary drawing.', 'Drawing quickly from memory rather than from looking.', 'Stopping to erase.'],
    ex: 'Do three blind contours of your non-drawing hand in different poses, then one modified contour where you look at the paper only about a fifth of the time.',
    kids: 'Make it a game: your eyes are a snail and the pencil follows the snail. Use felt-tip pens so nobody can erase.',
    adults: 'Use it to break perfectionism. Point out the sensitive, lively line quality and how much more they noticed.',
    mat: ['Fineliner or felt-tip pen', 'Pencil', 'A paper plate', 'Simple objects'], rel: ['marks', 'gesture', 'negative-space'] },
  { id: 'gesture', s: 'found', n: 'Gesture drawing', sum: 'Fast drawings that catch movement and pose, not details.', lvl: 1, mins: 20, ill: 'gesture',
    what: 'Gesture drawings are quick sketches, usually 30 seconds to two minutes, that capture the action, energy and weight of a pose. They start with one curved line of action through the body, then add simple shapes for the head, ribcage and hips.',
    why: 'Gesture gives figures and animals life and stops stiff, wooden poses. It also teaches students to see the whole before the details.',
    steps: ['Find the line of action: one long curve through the pose, usually from the head down the spine to the leg taking the weight.', 'Draw it lightly and quickly.', 'Add an oval for the head and egg shapes for the ribcage and hips, tilted as they are in the pose.', 'Add the limbs as simple lines or tubes, showing where the weight goes.', 'Stop when the time is up and move on to the next pose.'],
    tips: ['Use a timer and change poses often: 30 seconds, then one minute, then two.', 'Draw big, using the whole arm.', 'Exaggerate the curve a little. It reads as more alive.'],
    mistakes: ['Starting with the outline of the head or the face.', 'Stiff, straight stick figures.', 'Trying to finish each one instead of catching the action.'],
    ex: 'Draw ten 30-second gestures and five two-minute gestures of classmates, people in videos or figure photos.',
    kids: 'Play freeze: students take turns holding superhero or animal poses for 30 seconds while the others sketch.',
    adults: 'Use pose photos or classmates in costume. Gesture makes an excellent weekly warm-up.',
    mat: ['Cheap newsprint or printer paper', 'Soft pencil, charcoal or marker', 'A timer'], rel: ['figure', 'contour', 'animals'] },
  { id: 'shapes', s: 'found', n: 'Building with basic shapes', sum: 'Seeing spheres, boxes, cylinders and cones inside everything.', lvl: 1, mins: 25, ill: 'shapes',
    what: 'Almost anything can be built from four basic forms: the sphere, the box, the cylinder and the cone. Drawing these lightly first and then refining the outline is called construction.',
    why: 'Construction makes proportion and perspective easier, makes objects look solid, and gives students a way to draw from imagination as well as from life.',
    steps: ['Look at the object and ask which basic forms it’s made of.', 'Lightly draw the biggest form first, at roughly the right size and position.', 'Add the smaller forms, checking where they join.', 'Draw through the forms (show the hidden back edges lightly) to keep them solid.', 'Refine the outline over the top with a firmer line.', 'Erase the construction lines, or leave them as part of the drawing.'],
    tips: ['Keep construction lines very light.', 'Practise ellipses for the tops of cylinders and cones.', 'Draw forms, not flat shapes: a box rather than a square, a sphere rather than a circle.'],
    mistakes: ['Pressing hard on construction lines so they can’t be erased.', 'Starting with small details before the big shapes are right.', 'Using flat shapes instead of forms.'],
    ex: 'Draw a teapot, a torch and a toy, each first as basic forms and then refined.',
    kids: 'Hand out shape cards and challenge them to build an animal or a vehicle from circles, squares, triangles and rectangles.',
    adults: 'Connect it to product design sketching: everyday objects built inside boxes drawn in perspective.',
    mat: ['2H and 2B pencils', 'Eraser', 'Simple household objects'], rel: ['ellipses', 'animals', 'two-point'] },
  { id: 'sighting', s: 'found', n: 'Measuring and sighting', sum: 'Using a pencil at arm’s length to check proportions and angles.', lvl: 2, mins: 25, ill: 'sighting',
    what: 'Sighting means holding a pencil at arm’s length to compare sizes and angles in what you see. One part of the subject becomes a unit (say, the height of a cup) and everything else is measured in those units.',
    why: 'It fixes the most common problems in observational drawing: things too big, too small or leaning the wrong way. It replaces guessing with checking.',
    steps: ['Sit or stand in one place and keep your head still.', 'Hold the pencil at full arm’s length, elbow locked, and close one eye.', 'Line the tip of the pencil up with the top of a small part of the subject and slide your thumb to its bottom. That’s your unit.', 'Keeping your arm straight, count how many units tall and wide the whole subject is.', 'Mark these proportions lightly on the paper before drawing.', 'For angles, line the pencil up with an edge, then bring that angle down to the paper.'],
    tips: ['Keep the arm fully straight every time, or the measurements change.', 'Pick a small, clear unit, such as a jar lid or the height of a head.', 'Check the biggest relationships first (height against width), then the details.'],
    mistakes: ['Bending the elbow between measurements.', 'Copying the measurement itself onto the paper instead of using it as a ratio.', 'Moving between measurements.'],
    ex: 'Set up a bottle and a cup. Measure the cup as one unit, find how many units tall the bottle is, then draw both in proportion.',
    kids: 'For younger children, compare instead: is the bottle as tall as two cups or three?',
    adults: 'Use sighting for still life, landscape and portraits, and show how it also finds the angles of roofs and tables.',
    mat: ['Pencil', 'Paper on a board', 'Still life objects'], rel: ['still-life', 'face', 'grid-method'] },
  { id: 'negative-space', s: 'found', n: 'Negative space', sum: 'Drawing the shapes around and between things.', lvl: 1, mins: 20, ill: 'negative',
    what: 'Negative space is the space around and between objects, such as the gaps between the legs of a chair or the patches of sky between leaves. Drawing those shapes instead of the object often gives a more accurate result.',
    why: 'Our brains have strong ideas about what a chair or a hand looks like, and they get in the way. Negative shapes are unfamiliar, so we draw what we actually see.',
    steps: ['Choose a subject with clear gaps: a chair, a pot plant, a bike, a hand on a hip.', 'Draw a frame on the paper and choose a matching view.', 'Find one enclosed gap and draw its shape carefully.', 'Move to the neighbouring gap, sharing edges.', 'Shade or colour the negative shapes, leaving the object as bare paper.', 'Step back: the object appears from the shapes you didn’t draw.'],
    tips: ['Use a viewfinder to frame the view.', 'Treat each gap as an abstract puzzle piece.', 'Compare the sizes of the gaps with each other.'],
    mistakes: ['Slipping back into outlining the object.', 'Ignoring the frame edges, which are part of the negative shapes.', 'Making all the gaps the same size.'],
    ex: 'Draw a chair or a pot plant by shading only the spaces around and between its parts.',
    kids: 'Use a stool or a pair of scissors and colour in the gaps with a bright colour.',
    adults: 'Use it as a checking tool in any drawing: compare the negative shapes in the drawing with the real ones.',
    mat: ['Pencil or charcoal', 'Viewfinder', 'A chair or a plant'], rel: ['viewfinder', 'contour', 'notan'] },
  { id: 'grid-method', s: 'found', n: 'The grid method', sum: 'Copying a picture accurately one square at a time.', lvl: 1, mins: 40, ill: 'grid',
    what: 'The grid method divides a reference picture and the drawing paper into matching grids. You copy what’s in each square, one at a time, which keeps the proportions accurate.',
    why: 'It builds confidence in beginners and is a professional tool for enlarging images, for example for murals. It also trains careful looking at shapes and edges.',
    steps: ['Choose a reference photo and draw a grid over it, for example of 2 cm squares.', 'Lightly draw a matching grid on the paper. Bigger squares enlarge the picture.', 'Number the rows and letter the columns on both.', 'Copy one square at a time, noting where lines cross the grid.', 'When the outline is done, gently erase the grid.', 'Add values and details while looking at the whole picture again.'],
    tips: ['Draw the grid lightly so it erases cleanly.', 'Turn both the reference and the drawing upside down to copy shapes rather than things.', 'Diagonals across each square help with complicated pictures.'],
    mistakes: ['Pressing the grid lines in hard.', 'Copying squares out of order and losing your place.', 'Never looking at the whole, so the drawing feels stiff.'],
    ex: 'Copy a photo of an animal with a 3 cm grid, then shade it from the photo.',
    kids: 'Use a ready-printed grid and a simple cartoon. Small squares are easiest.',
    adults: 'Show how grids transfer designs onto canvas or walls, and talk about when to use one and when to draw freehand.',
    mat: ['Ruler', 'HB and 2B pencils', 'Eraser', 'A printed reference photo'], rel: ['sighting', 'animals', 'face'] },

  /* ---------- shading and tone ---------- */
  { id: 'value-scale', s: 'shade', n: 'Value scales', sum: 'A ladder of tones from white to black.', lvl: 1, mins: 20, ill: 'value',
    what: 'Value is how light or dark something is, whatever its colour. A value scale is a row of boxes stepping evenly from the white of the paper to the darkest dark your material can make, usually in five, seven or nine steps.',
    why: 'Value does most of the work in making things look real. Students who can make and see a full range of values draw with more depth and contrast straight away.',
    steps: ['Draw a row of five to nine joined boxes.', 'Leave the first box as clean white paper.', 'Fill the last box as dark as you can, layering a soft pencil such as 6B or 8B.', 'Fill the middle box with a grey halfway between.', 'Fill the remaining boxes so each step is even.', 'Squint at the scale: the steps should look evenly spaced, with no two the same.'],
    tips: ['Build darks in layers rather than pressing hard.', 'Use harder pencils for the light values and softer ones for the darks.', 'Hold the scale up beside a drawing to check its values.'],
    mistakes: ['Big jumps at the dark end and tiny ones at the light end.', 'Not going dark enough.', 'Smudged or patchy boxes.'],
    ex: 'Make a nine-step value scale, then shade a cube using just three of the values: light top, middle side, dark side.',
    kids: 'Make a five-step light-to-dark ladder in pencil, then a fun version in one colour of paint mixed with white.',
    adults: 'Punch a hole in each box to make a value finder they can hold up to the subject.',
    mat: ['2H, HB, 2B, 4B, 6B and 8B pencils', 'Ruler', 'Cartridge paper'], rel: ['light-form', 'graphite', 'notan'] },
  { id: 'light-form', s: 'shade', n: 'Light on form: the five tones', sum: 'Highlight, light, core shadow, reflected light and cast shadow.', lvl: 1, mins: 30, ill: 'sphere', cap: 'Light from the upper left. The reflected light stays darker than anything on the lit side.',
    what: 'When light falls on a rounded object it makes a predictable pattern: a highlight where light reflects straight back, the light side, the core shadow (the darkest band, where the form turns away from the light), reflected light bounced back into the shadow, and the cast shadow on the surface, darkest right where the object touches it.',
    why: 'Once students understand this pattern they can shade anything convincingly, from apples to faces, from life or from imagination.',
    steps: ['Decide where the light comes from and mark it with an arrow.', 'Draw the outline of the sphere and the shape of its cast shadow on the far side.', 'Lightly mark the border between light and shadow.', 'Shade the whole shadow side a mid-dark value.', 'Darken the core shadow just inside that border.', 'Lighten the edge of the shadow side a little for reflected light.', 'Shade the light side gently, leaving the highlight as clean paper.', 'Make the cast shadow darkest where it touches the object and softer further away.'],
    tips: ['Reflected light is always darker than any part of the lit side.', 'Squint to see the shadow shapes as simple blocks.', 'One lamp in a dim room shows the five tones clearly.'],
    mistakes: ['Reflected light so bright that the object looks hollow or glowing.', 'A dark outline all the way round.', 'Forgetting the contact shadow, so the object floats.'],
    ex: 'Shade a sphere, a cylinder and a cube under one lamp and label the five tones on each.',
    kids: 'Shine a torch on a ball in a dim room and spot the parts together before drawing.',
    adults: 'Apply it straight away to an egg, then to a face photo, pointing out the same tones.',
    mat: ['HB, 2B and 6B pencils', 'Blending stump', 'Kneaded eraser', 'A lamp and a ball or egg'], rel: ['cast-shadows', 'value-scale', 'blending'] },
  { id: 'hatching', s: 'shade', n: 'Hatching', sum: 'Parallel lines that build tone.', lvl: 1, mins: 20, ill: 'hatch',
    what: 'Hatching builds value with closely spaced parallel lines. The closer and heavier the lines, the darker the area looks. It’s the classic shading method for pen and ink, etching and pencil.',
    why: 'It’s clean and controllable, works with any line tool (including pens that can’t blend) and gives drawings a lively, crafted texture.',
    steps: ['Practise lines first: straight, parallel and evenly spaced, flicking the pencil so each line tapers.', 'Choose one direction. A diagonal is the most comfortable for most people.', 'For light areas, space the lines far apart.', 'For darker areas, bring them closer together, or press a little harder.', 'Keep the length and direction consistent within an area.', 'Leave highlights as untouched paper.'],
    tips: ['Turn the paper so you’re always making your most comfortable stroke.', 'Cover big areas with short, overlapping rows of hatching.', 'Keep a sharp point for crisp lines.'],
    mistakes: ['Lines that hook at the ends. Flick away cleanly.', 'Changing direction at random, which looks messy.', 'Pressing so hard the lines groove the paper.'],
    ex: 'Hatch a five-step value scale, then shade an apple using only hatching.',
    kids: 'Draw a sun and clouds and add hatched rain, closer together under the dark clouds.',
    adults: 'Look at old engravings and Renaissance drawings, which use hatching for everything.',
    mat: ['HB and 2B pencils, or fineliners', 'Smooth paper'], rel: ['cross-hatching', 'contour-hatching', 'pen-ink'] },
  { id: 'cross-hatching', s: 'shade', n: 'Cross-hatching', sum: 'Layers of hatching in new directions for darker values.', lvl: 1, mins: 25, ill: 'crosshatch',
    what: 'Cross-hatching adds layers of hatching at different angles over the first set. Each new layer darkens the area, so a full range of values can be built from lines alone.',
    why: 'It reaches deep darks with a pen and creates a rich, woven texture. It also teaches patience and planning, because values build gradually.',
    steps: ['Hatch the whole shadow area in one direction.', 'Add a second layer at about a right angle over the darker parts.', 'Add a third layer on a diagonal over the darker parts still.', 'Add a fourth layer only in the darkest darks.', 'Leave lighter areas with fewer layers and the highlights as paper.'],
    tips: ['Make each layer’s angle clearly different. Nearly matching angles make a wavy pattern.', 'Work light to dark, checking the values as you go.', 'Keep each layer as neat as the first.'],
    mistakes: ['Cross-hatching the whole drawing evenly, which flattens it.', 'Scribbly layers that lose the hatched look.', 'Going dark too soon.'],
    ex: 'Cross-hatch a mug or a jar in up to four layers, keeping the highlights clean.',
    kids: 'Make a tartan value ladder: one layer, two, three, four.',
    adults: 'Compare pens of different nib sizes, and look at how comic inkers build their darks.',
    mat: ['Fineliners 0.1 to 0.5, or HB and 2B pencils', 'Smooth paper'], rel: ['hatching', 'pen-ink', 'value-scale'] },
  { id: 'stippling', s: 'shade', n: 'Stippling', sum: 'Building tone with dots.', lvl: 1, mins: 30, ill: 'stipple',
    what: 'Stippling makes value with dots: a few scattered dots for light areas and many packed together for dark ones. From a distance the dots merge into smooth tone.',
    why: 'It gives beautifully soft gradations with a pen and suits textures such as stone, skin, sand and moss. It’s also very calming to do.',
    steps: ['Lightly pencil the outline and the shadow shapes.', 'Hold the pen upright and tap gently to make round dots, not dashes.', 'Start with the darkest areas, placing dots close together.', 'Work outwards, spacing the dots further apart as the value lightens.', 'Leave the highlights empty.', 'Step back often and add dots wherever the gradient looks patchy.'],
    tips: ['Keep the dots the same size and vary their spacing instead.', 'Turn the page and work in small circular patches so rows don’t form.', 'A fine pen (0.1 to 0.3) gives the smoothest result.'],
    mistakes: ['Dragging the pen, which makes commas instead of dots.', 'Dots lining up in rows.', 'Outlining the shape, which looks out of place in stippling.'],
    ex: 'Stipple a sphere, or a small object such as a pine cone or a shell, with no outline.',
    kids: 'Try pointillism with cotton buds and paint, or felt-tips, for a bright version.',
    adults: 'Use stippling for textures, and look at scientific illustration, which uses it a lot.',
    mat: ['Fineliners 0.1 to 0.5', 'Smooth paper or Bristol board', 'Pencil for the layout'], rel: ['textures', 'pen-ink', 'light-form'] },
  { id: 'circulism', s: 'shade', n: 'Circulism (scribble shading)', sum: 'Tiny overlapping circles for smooth, even tone.', lvl: 2, mins: 25, ill: 'circulism',
    what: 'Circulism shades with small, light, overlapping circles, layered until the paper is evenly covered. The texture is so fine that it reads as smooth tone, which suits skin, fruit and other soft surfaces.',
    why: 'It avoids the streaks of back-and-forth shading and the shine of heavy pressure, and gives an even tone without a blending tool.',
    steps: ['Use a sharp pencil and very light pressure.', 'Make tiny circles that overlap, moving slowly across the area.', 'Build up layers: each pass adds a little more value.', 'Use a softer pencil, or more layers, for darker areas.', 'Change the size of the circles for texture: tiny for smooth, larger for rough.'],
    tips: ['Keep the circles tiny and their direction random.', 'Light pressure and many layers is the secret.', 'Sharpen often so the point reaches into the paper’s texture.'],
    mistakes: ['Big loops that look like scribble rather than tone.', 'Pressing hard, which shines and can’t be layered.', 'Patchy coverage from rushing.'],
    ex: 'Shade an egg or a smooth stone with circulism until it looks as smooth as you can make it.',
    kids: 'Call them tiny snail shells and try them in coloured pencil on a piece of fruit.',
    adults: 'Compare a patch of circulism with a blended patch and a hatched one, and talk about which suits skin, fabric and metal.',
    mat: ['HB, 2B and 4B pencils', 'Smooth cartridge paper', 'Sharpener'], rel: ['blending', 'coloured-pencil', 'face'] },
  { id: 'blending', s: 'shade', n: 'Blending and smooth gradients', sum: 'Softening pencil into seamless tone.', lvl: 2, mins: 25, ill: 'blend',
    what: 'Blending smooths pencil or charcoal into even tone with a blending stump (tortillon), tissue, chamois or a soft brush. It makes seamless gradients for smooth, shiny subjects such as glass, metal and skin.',
    why: 'It gives a polished, photographic finish and handles subtle changes of tone. Knowing when not to blend matters just as much.',
    steps: ['Lay down an even layer of graphite, following the direction of the form.', 'With a clean stump, blend from light to dark with gentle pressure.', 'Use a darker stump, already loaded with graphite, for the dark areas.', 'Add more graphite and blend again to deepen values.', 'Lift highlights out with a kneaded eraser pinched to a point.', 'Finish with crisp edges and a few sharp marks so it doesn’t look fuzzy.'],
    tips: ['Blend from light to dark so you don’t drag graphite into the lights.', 'Keep separate stumps for light and dark values.', 'Fingers leave oils that cause blotches, so use tools instead.'],
    mistakes: ['Blending everything, which makes a drawing soft and woolly.', 'Smudging into the highlights.', 'Too little graphite, so the paper is just polished shiny.'],
    ex: 'Draw a marble, a spoon or a glass bauble with smooth gradients and sharp highlights.',
    kids: 'Blend a sunset in coloured pencil or chalk pastel with a tissue.',
    adults: 'Talk about edges: blend where a form turns gently, and keep edges crisp where it turns sharply.',
    mat: ['2B, 4B and 6B pencils', 'Blending stumps', 'Tissue or chamois', 'Kneaded eraser'], rel: ['circulism', 'light-form', 'charcoal'] },
  { id: 'contour-hatching', s: 'shade', n: 'Contour hatching', sum: 'Curved hatching that wraps around the form.', lvl: 2, mins: 25, ill: 'contourhatch',
    what: 'Contour hatching (also called cross-contour or bracelet shading) uses curved lines that follow the surface of a form, like bands wrapped around it. The curves describe the shape, while their spacing describes the value.',
    why: 'It makes forms look round and solid even in pen, and builds an understanding of how surfaces turn in space.',
    steps: ['Draw the outline and imagine slicing the object into thin sections.', 'Draw curved lines across the form, following its surface like bracelets.', 'Space the lines further apart on the light side.', 'Bring them closer together in shadow, or add a second set in another direction.', 'Keep the curves consistent so the surface reads clearly.'],
    tips: ['Practise on simple forms first: a cylinder, a sphere, a banana.', 'Ellipse practice helps, because the curves are parts of ellipses.', 'Notice how hair, fabric and wood grain naturally follow contours.'],
    mistakes: ['Curves bending the wrong way, which makes the form look hollow.', 'Straight lines on round forms.', 'Lines that ignore the edges of the form.'],
    ex: 'Shade a banana, a shell or a tree trunk with contour hatching only.',
    kids: 'Draw a fish or a snake and add curved stripes that wrap around its body.',
    adults: 'Look at the contour lines in engravings, then apply them to the limbs of a figure.',
    mat: ['Fineliner or HB pencil', 'Smooth paper'], rel: ['hatching', 'ellipses', 'shapes'] },
  { id: 'subtractive', s: 'shade', n: 'Subtractive drawing', sum: 'Toning the paper, then lifting out the lights.', lvl: 2, mins: 30, ill: 'subtract',
    what: 'Subtractive drawing starts by toning the whole page mid-grey with charcoal or graphite, then uses erasers to pull out the light areas and charcoal to push in the darks. You draw light into dark instead of dark onto white.',
    why: 'It encourages working in big masses of light and shadow, which looks dramatic and three-dimensional, and stops students outlining everything.',
    steps: ['Rub charcoal over the whole paper and smooth it with a tissue or chamois into an even mid-tone.', 'Lightly sketch the main shapes on top.', 'Use a kneaded eraser to lift out the large light areas.', 'Use a firm eraser or an eraser pen for the brightest highlights.', 'Add the darks with compressed charcoal.', 'Refine the edges, blending some and keeping others sharp.', 'Spray with fixative outdoors, or keep the drawing covered.'],
    tips: ['Knead the eraser into shapes: a point for small lights, a flat edge for broad areas.', 'Work from big shapes to small ones.', 'Keep a sheet of paper under your hand to avoid smudges.'],
    mistakes: ['Toning so dark that the lights won’t lift.', 'Outlining instead of working in shapes.', 'Heavy fixative, which darkens the drawing.'],
    ex: 'Tone the page mid-grey and lift out the lights of an egg and a cup lit by one lamp.',
    kids: 'Draw a night scene: tone the page, then switch on a moon and stars with an eraser.',
    adults: 'Use it for portraits from strongly lit photos.',
    mat: ['Willow or vine charcoal', 'Compressed charcoal', 'Kneaded and firm erasers', 'Tissue or chamois', 'Fixative', 'Cartridge or charcoal paper'], rel: ['charcoal', 'chiaroscuro', 'light-form'] },
  { id: 'cast-shadows', s: 'shade', n: 'Cast shadows', sum: 'The shadow an object throws, and how its edges change.', lvl: 2, mins: 25, ill: 'cast',
    what: 'A cast shadow is the shadow an object throws onto a surface. Its shape depends on the direction and height of the light, and its edge is sharpest and darkest near the object, getting softer and lighter further away.',
    why: 'Cast shadows anchor objects to the ground and describe the surface they fall on. Without them, things float.',
    steps: ['Work out the light’s direction and how high it is.', 'Find where the object touches the surface.', 'Map the shadow shape: a low light makes long shadows and a high light makes short ones.', 'Shade the shadow darkest at the point of contact.', 'Let it lighten and its edge soften as it moves away.', 'Bend the shadow over anything it crosses, such as steps or cloth.'],
    tips: ['Near the contact point, cast shadows are usually darker than the object’s own shadow side.', 'Use a single lamp to see the effect clearly.', 'Shadows pick up colour from the surface and the sky.'],
    mistakes: ['Hard edges all the way along.', 'Shadows from different objects going in different directions.', 'No contact shadow, so the object floats.'],
    ex: 'Light two objects with a lamp and draw their cast shadows, with hard edges near and soft edges far.',
    kids: 'Go outside and trace each other’s shadows in chalk at different times of day.',
    adults: 'Use perspective to plot the cast shadows of boxes from a lamp.',
    mat: ['HB, 2B and 4B pencils', 'A lamp', 'Simple objects'], rel: ['light-form', 'chiaroscuro', 'still-life'] },
  { id: 'chiaroscuro', s: 'shade', n: 'Chiaroscuro and dramatic light', sum: 'Strong contrast between light and dark for drama.', lvl: 3, mins: 45, ill: 'chiaro',
    what: 'Chiaroscuro (Italian for light-dark) uses strong contrast between light and dark to model form and create drama. One light source lights part of the subject, and the rest falls into deep shadow that merges with the background.',
    why: 'It creates mood and focus, and teaches students to see and simplify the big shapes of light and shadow.',
    steps: ['Light the subject from the side with one strong lamp in a dim room.', 'Squint and find the shapes of light. Everything else is shadow.', 'Tone or paint the background and the shadows dark.', 'Model the lit areas carefully, with gradual changes into shadow.', 'Let some edges disappear into the dark.', 'Add the brightest highlights last.'],
    tips: ['Toned or black paper with white and black materials gets a quick result.', 'Keep detail out of the shadows.', 'Look at Caravaggio and Rembrandt for inspiration.'],
    mistakes: ['Too many mid-tones, which kills the drama.', 'Outlining shapes in the dark areas.', 'Several lights confusing the shadows.'],
    ex: 'Draw an object lit by one lamp (lights low) emerging from a dark background.',
    kids: 'Draw by torchlight: white pencil on black paper, drawing only what the torch would light.',
    adults: 'Draw a portrait or still life in charcoal and white on toned paper.',
    mat: ['Charcoal and white chalk or pastel', 'Toned or black paper', 'A lamp'], rel: ['subtractive', 'light-form', 'charcoal'] },
  { id: 'textures', s: 'shade', n: 'Drawing textures', sum: 'Showing wood, fur, metal, glass and fabric with marks.', lvl: 2, mins: 30, ill: 'textures',
    what: 'Texture is how a surface feels, or would feel. In a drawing it comes from the marks and values you choose: wavy grain for wood, short directional strokes for fur, high contrast for metal, and clean edges with bright highlights for glass.',
    why: 'Convincing textures bring drawings to life and let different materials read instantly.',
    steps: ['Look closely: is the surface rough, smooth, shiny or matt?', 'Shade the overall light and shadow first, before any texture.', 'Choose marks to match: wavy lines for wood, flicked strokes for fur, dots for stone.', 'For shiny surfaces, put sharp highlights right next to very dark reflections.', 'For glass, draw what you see through it, distorted, plus bright edge highlights.', 'Show texture mostly in the mid-tones. It disappears in highlights and deep shadows.'],
    tips: ['Texture shows most where light and shadow meet.', 'Vary the marks so they don’t look mechanical.', 'Use close-up photos of surfaces as references.'],
    mistakes: ['Covering the whole object in texture marks.', 'Forgetting the light and shadow underneath.', 'Drawing every single hair or brick.'],
    ex: 'Make a texture sampler: wood, fur, brick, metal, glass and fabric in six squares.',
    kids: 'Make rubbings of leaves, coins and bark, then copy the textures by drawing them.',
    adults: 'Draw a still life of contrasting surfaces: a shiny kettle, a woolly scarf and a wooden spoon.',
    mat: ['Pencils HB to 6B', 'Fineliners', 'Kneaded eraser', 'Textured objects'], rel: ['marks', 'stippling', 'animals'] },

  /* ---------- perspective and space ---------- */
  { id: 'one-point', s: 'persp', n: 'One-point perspective', sum: 'Lines meeting at a single point on the horizon.', lvl: 1, mins: 40, ill: 'p1',
    what: 'One-point perspective shows depth when you look straight at a scene, such as down a road, a railway or a hallway. Lines going away from you meet at a single vanishing point on the horizon line, which is your eye level. Vertical lines stay vertical, and horizontal lines facing you stay horizontal.',
    why: 'It’s the simplest system for drawing rooms, streets and boxes that look right, and it gives students a big sense of achievement.',
    steps: ['Draw a horizon line across the page. This is your eye level.', 'Mark a vanishing point on the horizon.', 'Draw the front face of a box as a simple rectangle.', 'Draw lines from each corner of the box to the vanishing point.', 'Decide how deep the box is and draw its back edges parallel to the front edges.', 'Erase the extra construction lines.', 'Try boxes above, below and across the horizon line.'],
    tips: ['Use a ruler and light construction lines.', 'Boxes above the horizon show their underside, and boxes below show their top.', 'For a room, draw the back wall as a rectangle and join its corners to the corners of the page.'],
    mistakes: ['Back edges that aren’t parallel to the front.', 'Receding lines that miss the vanishing point.', 'Forgetting that the horizon is eye level.'],
    ex: 'Draw a road or hallway disappearing to one vanishing point, then add doors and windows.',
    kids: 'Draw a road to the horizon with trees getting smaller, then turn it into a town.',
    adults: 'Draw a dream room or a street, adding furniture as boxes first.',
    mat: ['Ruler', 'HB and 2H pencils', 'Eraser'], rel: ['two-point', 'depth-cues', 'shapes'] },
  { id: 'two-point', s: 'persp', n: 'Two-point perspective', sum: 'Objects seen from a corner, with two vanishing points.', lvl: 2, mins: 45, ill: 'p2',
    what: 'Two-point perspective is used when you see an object from its corner, like a building on a street corner. Its horizontal edges run to two vanishing points, one on each side of the horizon, while vertical lines stay vertical.',
    why: 'It makes buildings, boxes and furniture look realistic from most viewpoints.',
    steps: ['Draw a horizon line with a vanishing point near each end.', 'Draw a vertical line for the nearest corner of the box.', 'Join the top and bottom of that line to both vanishing points.', 'Draw two more vertical lines to set the width of each side.', 'Join the tops of these lines to the opposite vanishing points to find the back corner.', 'Darken the box’s edges and erase the guidelines.'],
    tips: ['Vanishing points that are too close together distort the box. Place them far apart, even off the page.', 'Start buildings from their nearest corner.', 'Shade one side darker for instant form.'],
    mistakes: ['Vertical lines that lean.', 'Mixing one-point and two-point lines in the same box.', 'Vanishing points that aren’t on the horizon.'],
    ex: 'Draw boxes above, on and below the horizon, then turn one into a building with doors and windows.',
    kids: 'Draw a simple house as a two-point box with a roof, then a street of them.',
    adults: 'Draw a street corner from imagination or a photo, with awnings and signs.',
    mat: ['Long ruler', 'HB and 2H pencils', 'Eraser', 'Masking tape for vanishing points off the page'], rel: ['one-point', 'three-point', 'shapes'] },
  { id: 'three-point', s: 'persp', n: 'Three-point perspective', sum: 'Looking up at, or down on, tall things.', lvl: 3, mins: 45, ill: 'p3',
    what: 'Three-point perspective adds a third vanishing point above or below the horizon, so vertical lines also converge. It shows dramatic views looking up at skyscrapers or down from a height.',
    why: 'It creates drama and a sense of scale, and it’s used in comics, games and architectural illustration.',
    steps: ['Draw a horizon line with two vanishing points far apart.', 'Place a third vanishing point well above the centre (looking up) or below it (looking down).', 'Draw the nearest vertical edge of the building heading towards the third point.', 'Join the base corners to the two side vanishing points.', 'Draw the other vertical edges towards the third vanishing point.', 'Find the top edges by joining to the side vanishing points.'],
    tips: ['The further away the third point, the gentler the effect.', 'Add windows with lines running to the vanishing points.', 'Exaggerate for drama, but sparingly.'],
    mistakes: ['Vertical edges that stay parallel.', 'The third point so close that the building distorts.', 'Losing track of which lines go to which point.'],
    ex: 'Draw a skyscraper seen from the footpath below.',
    kids: 'Draw a giant looking down on a tiny city, using a simplified version.',
    adults: 'Draw a city view looking down from a rooftop.',
    mat: ['Long ruler', 'Large paper', 'HB and 2H pencils'], rel: ['two-point', 'foreshortening', 'one-point'] },
  { id: 'atmospheric', s: 'persp', n: 'Atmospheric perspective', sum: 'Distant things look paler, bluer and softer.', lvl: 1, mins: 30, ill: 'atmos',
    what: 'Atmospheric (or aerial) perspective is the way air and moisture make distant things look lighter, bluer, lower in contrast and less detailed, while near things look darker, warmer, sharper and more detailed.',
    why: 'It’s the easiest way to create deep space in a landscape, in any medium.',
    steps: ['Plan three or four layers: foreground, middle ground, background and sky.', 'Paint or draw the furthest layer first, palest and coolest.', 'Make each nearer layer darker, warmer and more detailed.', 'Keep edges soft in the distance and crisp in the foreground.', 'Save the strongest contrast and detail for the foreground.'],
    tips: ['Mix a little sky colour into distant hills.', 'Squint at real landscapes to see how values flatten with distance.', 'Far mountains are often almost the same value as the sky.'],
    mistakes: ['Detailed trees in the far distance.', 'The same value for every layer.', 'Dark outlines around distant hills.'],
    ex: 'Paint or draw layered hills that get lighter and cooler as they go back.',
    kids: 'Make a layered landscape from torn strips of paper in four shades of blue.',
    adults: 'Paint a landscape in three values of one colour, then again in full colour.',
    mat: ['Watercolour, acrylic or pencils', 'Paper'], rel: ['depth-cues', 'temperature', 'skies'] },
  { id: 'depth-cues', s: 'persp', n: 'Overlap, size and placement', sum: 'Simple ways to show near and far.', lvl: 1, mins: 20, ill: 'overlap',
    what: 'Even without perspective lines, three simple cues show depth: overlap (things in front hide things behind), size (further things look smaller) and placement (further things sit higher on the page, nearer the horizon).',
    why: 'They’re easy, even for young children, and they work in any picture.',
    steps: ['Draw a horizon line about a third of the way down the page.', 'Draw one large object near the bottom of the page.', 'Draw a medium-sized one a little higher, partly hidden behind the first.', 'Draw small ones near the horizon.', 'Give distant objects less detail and paler colour.'],
    tips: ['Overlap is the strongest cue, so use plenty of it.', 'Keep size changes consistent for repeated things like trees or people.', 'Combine with atmospheric perspective.'],
    mistakes: ['Everything lined up along the bottom edge.', 'No overlap anywhere.', 'Distant things as big as near ones.'],
    ex: 'Draw a landscape with trees or houses that use overlap, size and placement.',
    kids: 'Cut out three sizes of trees and arrange them into a forest that goes back.',
    adults: 'Use these cues in quick landscape thumbnails before using full perspective.',
    mat: ['Pencils', 'Paper', 'Coloured pencils or paint'], rel: ['atmospheric', 'one-point', 'thirds'] },
  { id: 'ellipses', s: 'persp', n: 'Ellipses and cylinders', sum: 'Drawing round things in perspective.', lvl: 2, mins: 30, ill: 'ellipse',
    what: 'A circle seen at an angle becomes an ellipse. Ellipses are flatter near eye level and rounder the further above or below eye level they are. Cups, bottles, wheels and plates all need them.',
    why: 'Wrong ellipses, with pointy ends or flat bottoms, are the most common reason a still life looks odd.',
    steps: ['Draw a vertical centre line for the cylinder.', 'Draw the top ellipse across it, the same on both sides.', 'Draw the bottom ellipse rounder than the top, because it’s further below eye level.', 'Join the sides with straight vertical lines.', 'Draw the whole bottom ellipse lightly, then erase the hidden back.', 'Warm up with ellipses: whole-arm movement, going round a few times.'],
    tips: ['Ellipses have rounded ends, never points.', 'The widest part of an ellipse sits on the centre line.', 'Draw through the ellipse to get the hidden back right.'],
    mistakes: ['Pointed, lemon-shaped ellipses.', 'Flat bottoms on cups.', 'Top and bottom ellipses the same shape.'],
    ex: 'Draw cups, bottles and jars seen from different heights.',
    kids: 'Draw a stack of birthday cakes or a tall pile of plates.',
    adults: 'Draw a still life of glassware and ceramics with careful ellipses.',
    mat: ['HB pencil', 'Eraser', 'Cups and bottles'], rel: ['shapes', 'still-life', 'contour-hatching'] },
  { id: 'foreshortening', s: 'persp', n: 'Foreshortening', sum: 'Things pointing at you look shorter and overlap.', lvl: 3, mins: 30, ill: 'foreshort',
    what: 'Foreshortening is how an object pointing towards or away from you looks shorter than it really is, with the near end larger and overlapping the far end, like an arm reaching out of the picture.',
    why: 'It adds drama and realism to figures and objects and is essential for convincing poses.',
    steps: ['Look at the subject and notice how much shorter it appears.', 'Draw its parts as simple overlapping forms: cylinders for arms, boxes for hands.', 'Make the nearest part the largest.', 'Overlap each part over the one behind it.', 'Draw contour lines across the forms to show which way they point.', 'Check proportions by sighting, not by what you know.'],
    tips: ['Trust what you see, not the length you know it to be.', 'Overlapping contours are the key.', 'Photograph poses to practise from.'],
    mistakes: ['Drawing the arm at its full length.', 'Losing the overlaps, which flattens the form.', 'Ignoring the size change between near and far parts.'],
    ex: 'Draw a hand, or a pencil, pointing straight at you.',
    kids: 'Draw a superhero punching towards the viewer with a huge fist.',
    adults: 'Draw a figure lying down, seen from the feet.',
    mat: ['Pencils', 'A mirror or photos'], rel: ['figure', 'hands', 'three-point'] },

  /* ---------- composition ---------- */
  { id: 'thirds', s: 'comp', n: 'Rule of thirds and focal points', sum: 'Placing the main interest off-centre.', lvl: 1, mins: 20, ill: 'thirds',
    what: 'The rule of thirds divides a picture into a three-by-three grid. Placing the main subject, or focal point, where the lines cross, and the horizon on a third line, usually looks more natural and interesting than putting everything in the middle.',
    why: 'It’s a reliable starting point for planning pictures, and it introduces the idea that composition is a choice.',
    steps: ['Lightly divide the page into thirds both ways.', 'Decide on the focal point: what you want people to look at first.', 'Place it on or near one of the four crossing points.', 'Put the horizon on the upper or lower third line, not the middle.', 'Lead the eye to the focal point with contrast, detail or lines.'],
    tips: ['It’s a guide, not a law. Centred pictures can be powerful too.', 'Give the focal point the strongest contrast.', 'Leave space in front of moving subjects and faces looking sideways.'],
    mistakes: ['A horizon across the middle that cuts the picture in half.', 'Several competing focal points.', 'Important things touching the edges.'],
    ex: 'Sketch or photograph the same subject centred and on a thirds point, and compare.',
    kids: 'Lay a clear plastic grid over photos and find where the main thing sits.',
    adults: 'Look at famous paintings: where’s the focal point, and how does your eye travel?',
    mat: ['Pencil', 'Ruler', 'Paper, or a phone camera with grid lines'], rel: ['leading-lines', 'thumbnails', 'balance'] },
  { id: 'leading-lines', s: 'comp', n: 'Leading lines', sum: 'Lines in the picture that guide the eye.', lvl: 1, mins: 20, ill: 'leading',
    what: 'Leading lines are lines within a picture, such as roads, rivers, fences, shadows or edges, that guide the viewer’s eye to the focal point.',
    why: 'They make a picture easy to read and create a sense of movement and depth.',
    steps: ['Decide on the focal point.', 'Look for natural lines in the scene: paths, rivers, rows of trees, fences.', 'Place them so they lead from an edge or corner towards the focal point.', 'Avoid lines that lead straight out of the picture.', 'Use gentle S-curves for a wandering path.'],
    tips: ['Lines coming in from the bottom corners invite the viewer in.', 'Implied lines count too: a gaze, or a pointing arm.', 'Diagonals feel lively; horizontals feel calm.'],
    mistakes: ['Lines leading the eye off the page.', 'Lines pointing at nothing.', 'Too many competing lines.'],
    ex: 'Draw a path or a river that leads the eye to a house or a tree.',
    kids: 'Draw a winding road to a castle, with footprints to follow.',
    adults: 'Take photos on a walk looking for leading lines, then sketch the best one.',
    mat: ['Pencil or paint', 'Paper'], rel: ['thirds', 'one-point', 'thumbnails'] },
  { id: 'thumbnails', s: 'comp', n: 'Thumbnail sketches', sum: 'Small, fast sketches to plan a picture.', lvl: 1, mins: 15, ill: 'thumbs',
    what: 'Thumbnails are tiny, quick sketches, from stamp-sized to palm-sized, for trying out different compositions, crops and value plans before starting a finished piece.',
    why: 'They save hours spent on pieces that don’t work, and they teach students to think about the whole picture before the details.',
    steps: ['Draw several small rectangles in the same proportions as the final piece.', 'In each one, try a different arrangement: closer, further, higher, lower, cropped.', 'Use only three values: light, middle and dark.', 'Spend one or two minutes on each.', 'Pick the strongest one and develop it.'],
    tips: ['Keep them small, which forces simplicity.', 'Use a marker or a soft pencil so you can’t add detail.', 'Look at them from across the room and squint.'],
    mistakes: ['Making them too detailed.', 'Trying only one idea.', 'Ignoring the frame edges.'],
    ex: 'Make four thumbnails of one landscape photo, then develop the best one.',
    kids: 'Draw mini pictures on sticky notes and vote for the class favourite.',
    adults: 'Make thumbnails a habit before every piece.',
    mat: ['Soft pencil or grey markers', 'Sketchbook'], rel: ['notan', 'thirds', 'sketchbook'] },
  { id: 'balance', s: 'comp', n: 'Balance and visual weight', sum: 'Arranging shapes so a picture feels settled.', lvl: 2, mins: 20, ill: 'balance',
    what: 'Balance is how visual weight is spread across a picture. Large, dark, bright or detailed areas feel heavier. Symmetrical balance mirrors both sides; asymmetrical balance uses a small, heavy element to balance a large, light one, like a seesaw.',
    why: 'Balanced pictures feel calm and complete, and deliberate imbalance can create tension. Students learn to adjust a picture rather than just add more to it.',
    steps: ['Squint at the picture and notice which areas grab attention.', 'Decide whether it should feel symmetrical and calm, or asymmetrical and lively.', 'Balance a large shape near the centre with a smaller, stronger shape further out.', 'Adjust value, colour or detail to shift the weight.', 'Check it upside down or in a mirror.'],
    tips: ['A small bright colour can balance a large dull area.', 'Busy detail is heavy; empty space is light.', 'A mirror gives you fresh eyes.'],
    mistakes: ['All the weight on one side.', 'Filling every corner to balance it.', 'Perfect symmetry when movement was the goal.'],
    ex: 'Arrange cut paper shapes three ways (symmetrical, asymmetrical and unbalanced) and discuss each.',
    kids: 'Make a balanced sticker picture, and show balance with a ruler on a pencil as a seesaw.',
    adults: 'Rearrange a still life set-up to improve its balance, sketching each version.',
    mat: ['Coloured paper shapes', 'Glue', 'Paper'], rel: ['thirds', 'notan', 'still-life'] },
  { id: 'notan', s: 'comp', n: 'Notan (light and dark design)', sum: 'Designing with only black and white shapes.', lvl: 2, mins: 30, ill: 'notan',
    what: 'Notan is a Japanese design idea about the balance of light and dark. In class it usually means designing a picture in only two values, or cutting shapes from one side of a black square and flipping them across to the white side, like a mirror.',
    why: 'It trains students to see the big light and dark shapes that make strong compositions, without the distraction of detail or colour.',
    steps: ['Take a black paper square and a larger white sheet.', 'Cut shapes from one edge of the black square.', 'Glue the square onto the white sheet.', 'Flip each cut piece across the edge it came from and glue it down as a mirror image.', 'For drawing, simplify a photo into just two values with a marker.', 'Check that the design reads clearly from a distance.'],
    tips: ['Keep the shapes simple and bold.', 'Use every piece you cut out.', 'Try a three-value notan (black, grey and white) next.'],
    mistakes: ['Shapes too small and fiddly.', 'Losing or throwing away pieces.', 'Adding extra lines or detail.'],
    ex: 'Make a cut-paper notan, then a two-value marker study of a still life.',
    kids: 'Make a symmetrical cut-paper butterfly or face by flipping pieces across.',
    adults: 'Make two-value studies of master paintings to see their underlying structure.',
    mat: ['Black and white paper', 'Scissors', 'Glue stick', 'Black marker'], rel: ['value-scale', 'thumbnails', 'balance'] },
  { id: 'viewfinder', s: 'comp', n: 'Cropping with a viewfinder', sum: 'A simple window for choosing what to draw.', lvl: 1, mins: 15, ill: 'viewfinder',
    what: 'A viewfinder is a card with a rectangular window cut in it. Looking through it isolates part of a scene, making it easier to choose a composition and to judge positions against the edges.',
    why: 'Real scenes are overwhelming. A viewfinder simplifies the choice and shows how cropping changes a picture.',
    steps: ['Cut a window in card in the same proportions as your paper.', 'Hold it at arm’s length and close one eye.', 'Move it closer to include more and further away to include less.', 'Slide it around to find an interesting composition.', 'Notice where the main shapes meet the window’s edges and copy that onto the paper.'],
    tips: ['Mark thirds on the window edges with small ticks.', 'Keep the viewfinder at the same distance once you’ve chosen.', 'Two L-shaped cards make an adjustable viewfinder.'],
    mistakes: ['Changing the distance while drawing.', 'Always choosing the obvious centred view.', 'Not using the window edges to place shapes.'],
    ex: 'Find three different compositions in the same corner of a room and sketch each quickly.',
    kids: 'Make viewfinder cameras and go on a classroom photo hunt.',
    adults: 'Use one outdoors for landscape sketching.',
    mat: ['Card', 'Scissors or craft knife', 'Ruler'], rel: ['thirds', 'negative-space', 'thumbnails'] },
];
